INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(33111, 'Luke 17:4', 'Luke', 17, 4, 'او که هغه د ورځې اووه ځلې درسره بدي وکړي او هر ځل راشي او درته ووایي چې زما توبه ده، نو هغه وبخښه.» قوي ایمان', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke17_verse_4.mp3', '', 1761754199, 1761754199),
(33112, 'Luke 17:5', 'Luke', 17, 5, 'رسولانو عیسی ته وویل: «زمونږ ایمان قوي کړه.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke17_verse_5.mp3', '', 1761754199, 1761754199),
(33113, 'Luke 17:6', 'Luke', 17, 6, 'عیسی وویل: «که چېرې تاسو د شړشمو د دانې په اندازه ایمان لرلی، نو تاسو کولای شول د توت دې ونې ته ووایئ چې له بېخه راووځه او په بحیرې کې راشنه شه. نو هغې به ستاسو خبره منلې وای. د یو نوکر وظیفه', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke17_verse_6.mp3', '', 1761754199, 1761754199),
(33114, 'Luke 17:7', 'Luke', 17, 7, 'فرض کړئ په تاسو کې کوم څوک نوکر لري چې قلبه کوي یا پسونه ساتي. کله چې هغه د پټي نه راشي ایا بادار به ورته ووایي چې زر راشه، کښېنه او ډوډۍ وخوره؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke17_verse_7.mp3', '', 1761754199, 1761754199),
(33115, 'Luke 17:8', 'Luke', 17, 8, 'هېڅکله نه! د دې په ځای به هغه ته ووایي: ‹ماته د ماښام ډوډۍ تیاره کړه، ملا دې وتړه او ترڅو پورې چې زه ډوډۍ خورم زما خدمت کوه، له هغې وروسته کولای شې چې خپله ډوډۍ وخورې.›', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke17_verse_8.mp3', '', 1761754199, 1761754199),
(33116, 'Luke 17:9', 'Luke', 17, 9, 'ایا بادار به د هغه نوکر څخه چې د هغه امر یې په ځای کړی دی، مننه وکړي؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke17_verse_9.mp3', '', 1761754199, 1761754199),
(33117, 'Luke 17:10', 'Luke', 17, 10, 'او په همدې ډول کله چې تاسو هم خپل ټول کارونه چې درته حکم شوی دی سرته ورسوئ، نو ووایئ: ‹مونږ نوکران د شاباسي وړ نه یو، مونږ یوازې خپله وظیفه سرته رسولې ده.›» عیسی لسو جذامیانو ته شفا ورکوي', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke17_verse_10.mp3', '', 1761754199, 1761754199),
(33118, 'Luke 17:11', 'Luke', 17, 11, 'کله چې عیسی اورشلیم ته تللو، نو د جلیل او سامرې ترمنځ په پوله تېر شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke17_verse_11.mp3', '', 1761754199, 1761754199),
(33119, 'Luke 17:12', 'Luke', 17, 12, 'هغه یو کلي ته د ننوتلو په وخت کې د لسو تنو سره چې د جذام په ناروغۍ اخته وو، مخامخ شو. هغوی لېرې ودرېدل', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke17_verse_12.mp3', '', 1761754199, 1761754199),
(33120, 'Luke 17:13', 'Luke', 17, 13, 'او په لوړ اواز یې نارې کړې: «ای عیسی باداره! په مونږ رحم وکړه.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke17_verse_13.mp3', '', 1761754199, 1761754199),
(33121, 'Luke 17:14', 'Luke', 17, 14, 'عیسی هغوی ته وکتل او ورته ویې ویل: «لاړ شئ او خپل ځانونه کاهنانو ته وښایئ.» څنګه چې هغوی روان شول، نو پاک او روغ شول.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke17_verse_14.mp3', '', 1761754199, 1761754199),
(33122, 'Luke 17:15', 'Luke', 17, 15, 'کله چې په هغوی کې یو تن ولیدل چې روغ شوی دی، نو بېرته راوګرځېد او په لوړ اواز یې د خدای ثنا وویله.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke17_verse_15.mp3', '', 1761754199, 1761754199),
(33123, 'Luke 17:16', 'Luke', 17, 16, 'هغه د عیسی په پښو کې پرېوت او د هغه څخه یې مننه وکړه. دا سړی یو سامری ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke17_verse_16.mp3', '', 1761754199, 1761754199),
(33124, 'Luke 17:17', 'Luke', 17, 17, 'عیسی وویل: «ایا ټول لس تنه پاک او روغ نه شول؟ نو بیا هغه نور نهه تنه چېرته دي؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke17_verse_17.mp3', '', 1761754199, 1761754199),
(33125, 'Luke 17:18', 'Luke', 17, 18, 'ایا له دې پردي سړي پرته بل څوک نه ؤ چې بېرته راغلی وای او د خدای ثنا یې ویلې وای؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke17_verse_18.mp3', '', 1761754199, 1761754199),
(33126, 'Luke 17:19', 'Luke', 17, 19, 'عیسی هغه سړي ته وویل: «پاڅېږه او لاړ شه، خپل ایمان ته روغ کړې.» د خدای د پاچاهۍ راتګ (متي ۲۴‏:‌۲۳‌‏-‌۲۸،‌۳۷‌‏-‌۴۱)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke17_verse_19.mp3', '', 1761754199, 1761754199),
(33127, 'Luke 17:20', 'Luke', 17, 20, 'ځینو فریسیانو د عیسی څخه پوښتنه وکړه چې د خدای پاچاهي به کله راشي. عیسی ځواب ورکړ: «د خدای پاچاهي په داسې ډول نه راځي چې هغه ولیدل شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke17_verse_20.mp3', '', 1761754199, 1761754199),
(33128, 'Luke 17:21', 'Luke', 17, 21, 'نه به هم څوک ووایي چې ګورئ، دلته ده‎ یا هلته ده. ځکه چې په حقیقت کې د خدای پاچاهي ستاسو په منځ کې ده.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke17_verse_21.mp3', '', 1761754199, 1761754199),
(33129, 'Luke 17:22', 'Luke', 17, 22, 'بیا یې شاګردانو ته وویل: «داسې وخت به راشي چې تاسو به په دې ارمان یئ چې هغه ورځ وګورئ چې د انسان زوی پاچاهي کوي، خو وبه یې نه وینئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke17_verse_22.mp3', '', 1761754199, 1761754199),
(33130, 'Luke 17:23', 'Luke', 17, 23, 'خلک به تاسو ته ووایي چې وګورئ دلته دی یا وګورئ هلته دی. خو تاسو هغوی پسې مه ځئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke17_verse_23.mp3', '', 1761754199, 1761754199),
(33131, 'Luke 17:24', 'Luke', 17, 24, 'ځکه په کومه ورځ چې د انسان زوی راځي د هغې برېښنا په شان به وي چې د اسمان له یو سر څخه تر بله سره پورې ځلیږي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke17_verse_24.mp3', '', 1761754199, 1761754199),
(33132, 'Luke 17:25', 'Luke', 17, 25, 'خو لومړی باید هغه ډېر کړاوونه وزغمي او د دې زمانې د خلکو له خوا به رد شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke17_verse_25.mp3', '', 1761754199, 1761754199),
(33133, 'Luke 17:26', 'Luke', 17, 26, 'لکه څنګه چې د نوح په زمانه کې شوي وو، همداسې به د انسان د زوی په زمانه کې هم وشي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke17_verse_26.mp3', '', 1761754199, 1761754199),
(33134, 'Luke 17:27', 'Luke', 17, 27, 'خلکو تر هغې ورځې پورې خوړل، څښل او ودونه به یې کول، ترڅو چې نوح کشتۍ ته ننوت او سېلاب راغی او ټول یې تباه کړل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke17_verse_27.mp3', '', 1761754199, 1761754199),
(33135, 'Luke 17:28', 'Luke', 17, 28, 'د لوط په زمانه کې همداسې شوي وو چې هغوی به خوړل، څښل، اخیستل او خرڅول، کرنه یې کوله او ودانۍ به یې جوړولې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke17_verse_28.mp3', '', 1761754199, 1761754199),
(33136, 'Luke 17:29', 'Luke', 17, 29, 'خو په هغه ورځ چې لوط د سدوم څخه لاړ، نو د اسمان څخه اور او د ګوګړو باران راواورېد او هغوی ټول یې تباه کرل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke17_verse_29.mp3', '', 1761754199, 1761754199),
(33137, 'Luke 17:30', 'Luke', 17, 30, 'په هغه ورځ چې د انسان زوی راښکاره شي، نو همداسې به وشي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke17_verse_30.mp3', '', 1761754199, 1761754199),
(33138, 'Luke 17:31', 'Luke', 17, 31, 'په هغه ورځ څوک چې د بام په سر وي او سامان یې په کوټه کې وي، نو هغه دې د خپل سامان د وړلو دپاره راښکته نه شي. همدارنګه څوک چې په پټي کې وي، نو خپل کور ته دې ته بېرته لاړ نه شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke17_verse_31.mp3', '', 1761754199, 1761754199),
(33139, 'Luke 17:32', 'Luke', 17, 32, 'د لوط ښځه در په یاد کړئ چې د هغې سره څه وشول.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke17_verse_32.mp3', '', 1761754199, 1761754199),
(33140, 'Luke 17:33', 'Luke', 17, 33, 'هرڅوک چې د خپل ځان د ساتلو کوښښ وکړي، نو هغه به له لاسه ورکړي او څوک چې خپل ځان له لاسه ورکړي، نو هغه به یې وژغوري.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke17_verse_33.mp3', '', 1761754199, 1761754199),
(33141, 'Luke 17:34', 'Luke', 17, 34, 'زه تاسو ته وایم، په هغه شپه که چېرې دوه تنه په یو کټ کې پراته وي، یو به یې بوتلل شي او بل به پرېښودل شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke17_verse_34.mp3', '', 1761754199, 1761754199),
(33142, 'Luke 17:35', 'Luke', 17, 35, 'د دوو ښځو څخه چې یوځای سره میچن کوي، یوه به یې بوتلل شي او بله به پرېښودل شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke17_verse_35.mp3', '', 1761754199, 1761754199),
(33143, 'Luke 17:36', 'Luke', 17, 36, 'که چېرې دوه سړي په پټي کې وي، نو یو به یې بوتلل شي او بل به پرېښودل شي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke17_verse_36.mp3', '', 1761754199, 1761754199),
(33144, 'Luke 17:37', 'Luke', 17, 37, 'شاګردانو د هغه څخه پوښتنه وکړه: «چېرته، ای استاذه؟» عیسی په ځواب کې وویل: «چېرته چې مرداره وي، هلته ټپوسان راټولیږي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke17_verse_37.mp3', '', 1761754199, 1761754199),
(33145, 'Luke 20:1', 'Luke', 20, 1, 'یوه ورځ کله چې عیسی د خدای په کور کې خلکو ته تعلیم ورکاوه او زېری یې ورته رسولو، مشران کاهنان او د شریعت عالمان د نورو یهودي مشرانو سره راغلل', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke20_verse_1.mp3', '', 1761754199, 1761754199),
(33146, 'Luke 20:2', 'Luke', 20, 2, 'او هغه ته یې وویل: «ته څه حق لرې چې دا کارونه کوې؟ چا تاته دا اختیار درکړی دی؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke20_verse_2.mp3', '', 1761754199, 1761754199),
(33147, 'Luke 20:3', 'Luke', 20, 3, 'عیسی هغوی ته په ځواب کې وویل: «زه هم ستاسو څخه یوه پوښتنه کوم، ماته ووایئ چې', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke20_verse_3.mp3', '', 1761754199, 1761754199),
(33148, 'Luke 20:4', 'Luke', 20, 4, 'د یحیی د تعمید ورکول د خدای له خوا ؤ یا د انسان له خوا؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke20_verse_4.mp3', '', 1761754199, 1761754199),
(33149, 'Luke 20:5', 'Luke', 20, 5, 'هغوی په خپل منځ کې بحث وکړ او ویل یې: «که چېرې ووایو چې د خدای له خوا ؤ، نو هغه به ووایي چې بیا تاسو ولې په هغه باندې ایمان رانه وړ؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke20_verse_5.mp3', '', 1761754199, 1761754199),
(33150, 'Luke 20:6', 'Luke', 20, 6, 'خو که چېرې ووایو چې د انسان له خوا ؤ، نو ټول خلک به مونږ سنګسار کړي، ځکه چې هغوی په دې عقیده دي چې یحیی پیغمبر ؤ.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke20_verse_6.mp3', '', 1761754199, 1761754199),
(33151, 'Luke 20:7', 'Luke', 20, 7, 'نو ځواب یې ورکړ: «مونږ نه پوهېږو چې د کوم ځای ؤ.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke20_verse_7.mp3', '', 1761754199, 1761754199),
(33152, 'Luke 20:8', 'Luke', 20, 8, 'عیسی هغوی ته وویل: «زه هم تاسو ته نه وایم چې په کوم اختیار دا کارونه کوم.» د انګورو د باغ او باغوانانو مثال (متي ۲۱‏:‌۳۳‌‏-‌۴۶ او مرقوس ۱۲‏:‌۱‌‏-‌۱۲)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke20_verse_8.mp3', '', 1761754199, 1761754199),
(33153, 'Luke 20:9', 'Luke', 20, 9, 'بیا عیسی خلکو ته دا مثال راوړ: «یو سړي د انګورو باغ جوړ کړ او هغه یې باغوانانو ته په اجاره ورکړ او په خپله د اوږدې مودې دپاره یو بل وطن ته لاړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke20_verse_9.mp3', '', 1761754199, 1761754199),
(33154, 'Luke 20:10', 'Luke', 20, 10, 'کله چې د انګورو د راټولولو وخت راورسېد، نو هغه خپل یو نوکر باغوانانو ته ورولېږه چې د باغ د حاصلاتو څخه د هغه برخه راوړي. خو باغوانانو هغه وواهه او تش لاس یې بېرته ولېږه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke20_verse_10.mp3', '', 1761754199, 1761754199),
(33155, 'Luke 20:11', 'Luke', 20, 11, 'بیا هغه بل نوکر ورولېږه، خو باغوانانو هغه هم وواهه، هغه یې بې‌عزته کړ او تش لاس یې بېرته ولېږه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke20_verse_11.mp3', '', 1761754199, 1761754199),
(33156, 'Luke 20:12', 'Luke', 20, 12, 'بیا یې درېم نوکر ورولېږه، خو هغه یې هم ټپي کړ او دباندې یې وغورځاوه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke20_verse_12.mp3', '', 1761754199, 1761754199),
(33157, 'Luke 20:13', 'Luke', 20, 13, 'د باغ خاوند د خپل ځان سره وویل: ‹اوس څه وکړم؟ زه به خپل ګران زوی ورولېږم، کېدای شي چې د هغه لحاظ وکړي.›', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke20_verse_13.mp3', '', 1761754199, 1761754199),
(33158, 'Luke 20:14', 'Luke', 20, 14, 'خو کله چې باغوانانو هغه ولیده، نو یو بل ته یې سره وویل: ‹دا یې وارث دی. راځئ چې مړ یې کړو، نو میراث به یې زمونږ شي.›', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke20_verse_14.mp3', '', 1761754199, 1761754199),
(33159, 'Luke 20:15', 'Luke', 20, 15, 'نو هغه یې د انګورو د باغ څخه دباندې وویست او ویې واژه.» عیسی پوښتنه وکړه: «د باغ خاوند به اوس د هغوی سره څه کوي؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke20_verse_15.mp3', '', 1761754199, 1761754199),
(33160, 'Luke 20:16', 'Luke', 20, 16, 'هغه به راشي او دا باغوانان به مړه کړي او د انګورو باغ به نورو ته ورکړي.» کله چې خلکو دا واورېدل، نو ویې ویل: «خدای دې نه کړي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke20_verse_16.mp3', '', 1761754199, 1761754199),
(33161, 'Luke 20:17', 'Luke', 20, 17, 'عیسی هغوی ته په ځیر سره وکتل او پوښتنه یې وکړه: «نو بیا د زبور د کتاب د دې برخې معنی څه ده؟ کومه تیږه چې رد کړې ګلکارانو وه هغه اوس شوه اصلي تیږه د تهداب', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke20_verse_17.mp3', '', 1761754199, 1761754199),
(33162, 'Luke 20:18', 'Luke', 20, 18, 'هرڅوک چې په دې تیږه راولویږي، نو ټوټې ټوټې به شي او که هغه تیږه په چا باندې راولویږي، نو هغه به ذرې ذرې کړي.» د مالیې ورکولو په هکله پوښتنه (متي ۲۲‏:‌۱۵‌‏-‌۲۲ او مرقوس ۱۲‏:‌۱۳‌‏-‌۱۷)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke20_verse_18.mp3', '', 1761754199, 1761754199),
